/// `Mfc2`.
///
/// Cut: GPR, LANE.
pub(super) fn Mfc2(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::Mfc2;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 16) & 0x1f;
    let s2: u128 = (w >> 11) & 0x1f;
    let s3: u128 = (w >> 7) & 0xf;
    let s5: i128 = s3 as i128;
    let v6 = st.vpr(b, (s2) as u8);
    let v7 = rt::rotl_bytes(b, v6, (s5) as i128);
    let v8 = b.extract(v7, 112, Width::new(16));
    let v9 = b.sext(v8, Width::new(64));
    st.set_gpr(b, (s1) as u8, v9, None);
    Ok(())
}

/// `Cfc2`.
///
/// Cut: GPR, SYS.
pub(super) fn Cfc2(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::Cfc2;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 16) & 0x1f;
    let s2: u128 = (w >> 11) & 0x1f;
    let s4: u128 = (s2 >> 0) & 0x3;
    let s5: bool = s4 == 0x0u128;
    let v6 = st.reg(b, "VCOL");
    let s8: u128 = (s2 >> 0) & 0x3;
    let s9: bool = s8 == 0x1u128;
    let v11 = st.reg(b, "VCCL");
    let v14 = st.reg(b, "VCE");
    let v15 = if s9 { v11 } else { v14 };
    let v16 = if s5 { v6 } else { v15 };
    let s17: u128 = (s2 >> 0) & 0x3;
    let s18: bool = s17 == 0x0u128;
    let v19 = st.reg(b, "VCOH");
    let s21: u128 = (s2 >> 0) & 0x3;
    let s22: bool = s21 == 0x1u128;
    let v24 = st.reg(b, "VCCH");
    let v27 = b.konst(Width::new(128), 0x0);
    let v28 = if s22 { v24 } else { v27 };
    let v29 = if s18 { v19 } else { v28 };
    let v30 = b.konst(Width::new(128), 0x10002000400080010002000400080);
    let v31 = b.bin(BinOp::And, v16, v30);
    let v32 = b.konst(Width::new(128), 0x1000200040008001000200040008000);
    let v33 = b.bin(BinOp::And, v29, v32);
    let v34 = b.bin(BinOp::Or, v31, v33);
    let v35 = b.konst(Width::new(128), 64u128);
    let v36 = b.bin(BinOp::LShr, v34, v35);
    let v37 = b.bin(BinOp::Or, v34, v36);
    let v38 = b.konst(Width::new(128), 32u128);
    let v39 = b.bin(BinOp::LShr, v37, v38);
    let v40 = b.bin(BinOp::Or, v37, v39);
    let v41 = b.konst(Width::new(128), 16u128);
    let v42 = b.bin(BinOp::LShr, v40, v41);
    let v43 = b.bin(BinOp::Or, v40, v42);
    let v44 = b.extract(v43, 0, Width::new(16));
    let v45 = b.sext(v44, Width::new(64));
    st.set_gpr(b, (s1) as u8, v45, None);
    Ok(())
}

/// `Mtc2`.
///
/// Cut: GPR, LANE.
pub(super) fn Mtc2(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::Mtc2;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 16) & 0x1f;
    let s2: u128 = (w >> 11) & 0x1f;
    let s3: u128 = (w >> 7) & 0xf;
    let s5: i128 = s3 as i128;
    let v6 = st.gpr(b, (s1) as u8);
    let v7 = b.extract(v6, 0, Width::new(16));
    let v8 = b.zext(v7, Width::new(128));
    let v9 = b.konst(Width::new(128), 112u128);
    let v10 = b.bin(BinOp::Shl, v8, v9);
    let s11: i128 = (8i128).wrapping_mul(s5);
    let v12 = b.konst(Width::new(128), (s11) as u128);
    let v13 = b.bin(BinOp::LShr, v10, v12);
    let s14: i128 = (8i128).wrapping_mul(s5);
    let s15: u128 = rt::lshr(0xffff0000000000000000000000000000u128, s14);
    let v16 = st.vpr(b, (s2) as u8);
    let v17 = b.konst(Width::new(128), s15);
    let v18 = b.lane_select(v17, v13, v16);
    st.set_vpr(b, (s2) as u8, v18, None);
    Ok(())
}

/// `Ctc2`.
///
/// Cut: GPR, LANE, SYS.
pub(super) fn Ctc2(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::Ctc2;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 16) & 0x1f;
    let s2: u128 = (w >> 11) & 0x1f;
    let v4 = st.gpr(b, (s1) as u8);
    let v5 = b.extract(v4, 0, Width::new(16));
    let v6 = b.lane1(LaneKind::Splat, LaneWidth::L16, v5);
    let v7 = b.konst(Width::new(128), 0x10002000400080010002000400080);
    let v8 = b.lane2(LaneKind::And, LaneWidth::L64, v6, v7);
    let v9 = b.konst(Width::new(128), 0x0);
    let v10 = b.lane2(LaneKind::Ne, LaneWidth::L16, v8, v9);
    let v11 = b.konst(Width::new(128), 0x1000200040008001000200040008000);
    let v12 = b.lane2(LaneKind::And, LaneWidth::L64, v6, v11);
    let v13 = b.konst(Width::new(128), 0x0);
    let v14 = b.lane2(LaneKind::Ne, LaneWidth::L16, v12, v13);
    let s15: u128 = (s2 >> 0) & 0x3;
    let s16: bool = s15 == 0x0u128;
    if s16 {
        st.set_reg(b, "VCOL", v10, None);
    }
    if s16 {
        st.set_reg(b, "VCOH", v14, None);
    }
    let s17: bool = !s16;
    let s18: u128 = (s2 >> 0) & 0x3;
    let s19: bool = s18 == 0x1u128;
    let s20: bool = s17 && s19;
    if s20 {
        st.set_reg(b, "VCCL", v10, None);
    }
    if s20 {
        st.set_reg(b, "VCCH", v14, None);
    }
    let s21: bool = !s19;
    let s22: bool = s17 && s21;
    if s22 {
        st.set_reg(b, "VCE", v10, None);
    }
    Ok(())
}

